  ('home_features_json', '[{"title":"Live dashboard","body":"Temperature, wind, rain, pressure, and sun times from your WeatherLink station."},{"title":"TV share links","body":"Fullscreen public URLs for lobbies, offices, and wall displays."},{"title":"Secure credentials","body":"WeatherLink API keys encrypted at rest. Choose v1 or v2 — never both."},{"title":"Cloud-native","body":"Runs on Cloudflare Workers worldwide. No local server to babysit."}]', strftime('%s','now') * 1000),
